import{_ as l,a0 as d,w as o,s as c,ao as t,I as i,x as n,a1 as p,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"深入学习 Linux 内核模块 | LCTT x X-CMD","titleTemplate":false,"description":"深入学习 Linux 内核模块 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"深入学习 Linux 内核模块 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"深入学习 Linux 内核模块 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190501 Looking into Linux modules","title":"深入学习 Linux 内核模块","tag":"201907","desc":""},"relativePath":"201907/20190501 Looking into Linux modules.md","filePath":"[post].md"}'),r={name:"201907/20190501 Looking into Linux modules.md"};function _(h,s,m,k,u,g){const a=d("Link");return o(),c("div",null,[s[15]||(s[15]=t(`<h1 id="深入学习-linux-内核模块" tabindex="-1">深入学习 Linux 内核模块 <a class="header-anchor" href="#深入学习-linux-内核模块" aria-label="Permalink to “深入学习 Linux 内核模块”">​</a></h1><blockquote><p>lsmod 命令能够告诉你当前系统上加载了哪些内核模块，以及关于使用它们的一些有趣的细节。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/04/modules-100794941-large.jpg" alt="Rob Oo CC BY 2.0"></p><h3 id="什么是-linux-内核模块" tabindex="-1">什么是 Linux 内核模块？ <a class="header-anchor" href="#什么是-linux-内核模块" aria-label="Permalink to “什么是 Linux 内核模块？”">​</a></h3><p>内核模块是可以根据需要加载到内核中或从内核中卸载的代码块，因此无需重启就可以扩展内核的功能。事实上，除非用户使用类似 <code>lsmod</code> 这样的命令来查询模块信息，否则用户不太可能知道内核发生的任何变化。</p><p>需要知道的重要一点是，在你的 Linux 系统上总会有<em>很多</em>可用的模块，并且如果你可以深入其中了解到很多细节。</p><p><code>lsmod</code> 的主要用途之一是在系统不能正常工作时检查模块。然而，大多数情况下，模块会根据需要加载的，而且用户不需要知道它们如何运作。</p><h3 id="显示内核模块" tabindex="-1">显示内核模块 <a class="header-anchor" href="#显示内核模块" aria-label="Permalink to “显示内核模块”">​</a></h3><p>显示内核模块最简单的方法是使用 <code>lsmod</code> 命令。虽然这个命令包含了很多细节，但输出却是非常用户友好。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsmod</span></span>
<span class="line"><span>Module                  Size  Used by</span></span>
<span class="line"><span>snd_hda_codec_realtek 114688  1</span></span>
<span class="line"><span>snd_hda_codec_generic  77824  1 snd_hda_codec_realtek</span></span>
<span class="line"><span>ledtrig_audio          16384  2 snd_hda_codec_generic,snd_hda_codec_realtek</span></span>
<span class="line"><span>snd_hda_codec_hdmi     53248  1</span></span>
<span class="line"><span>snd_hda_intel          40960  2</span></span>
<span class="line"><span>snd_hda_codec         131072  4 snd_hda_codec_generic,snd_hda_codec_hdmi,snd_hda_intel</span></span>
<span class="line"><span>                                ,snd_hda_codec_realtek</span></span>
<span class="line"><span>snd_hda_core           86016  5 snd_hda_codec_generic,snd_hda_codec_hdmi,snd_hda_intel</span></span>
<span class="line"><span>                                ,snd_hda_codec,snd_hda_codec_realtek</span></span>
<span class="line"><span>snd_hwdep              20480  1 snd_hda_codec</span></span>
<span class="line"><span>snd_pcm               102400  4 snd_hda_codec_hdmi,snd_hda_intel,snd_hda_codec,snd_hda</span></span>
<span class="line"><span>                                _core</span></span>
<span class="line"><span>snd_seq_midi           20480  0</span></span>
<span class="line"><span>snd_seq_midi_event     16384  1 snd_seq_midi</span></span>
<span class="line"><span>dcdbas                 20480  0</span></span>
<span class="line"><span>snd_rawmidi            36864  1 snd_seq_midi</span></span>
<span class="line"><span>snd_seq                69632  2 snd_seq_midi,snd_seq_midi_event</span></span>
<span class="line"><span>coretemp               20480  0</span></span>
<span class="line"><span>snd_seq_device         16384  3 snd_seq,snd_seq_midi,snd_rawmidi</span></span>
<span class="line"><span>snd_timer              36864  2 snd_seq,snd_pcm</span></span>
<span class="line"><span>kvm_intel             241664  0</span></span>
<span class="line"><span>kvm                   626688  1 kvm_intel</span></span>
<span class="line"><span>radeon               1454080  10</span></span>
<span class="line"><span>irqbypass              16384  1 kvm</span></span>
<span class="line"><span>joydev                 24576  0</span></span>
<span class="line"><span>input_leds             16384  0</span></span>
<span class="line"><span>ttm                   102400  1 radeon</span></span>
<span class="line"><span>drm_kms_helper        180224  1 radeon</span></span>
<span class="line"><span>drm                   475136  13 drm_kms_helper,radeon,ttm</span></span>
<span class="line"><span>snd                    81920  15 snd_hda_codec_generic,snd_seq,snd_seq_device,snd_hda</span></span>
<span class="line"><span>                                 _codec_hdmi,snd_hwdep,snd_hda_intel,snd_hda_codec,snd</span></span>
<span class="line"><span>                                 _hda_codec_realtek,snd_timer,snd_pcm,snd_rawmidi</span></span>
<span class="line"><span>i2c_algo_bit           16384  1 radeon</span></span>
<span class="line"><span>fb_sys_fops            16384  1 drm_kms_helper</span></span>
<span class="line"><span>syscopyarea            16384  1 drm_kms_helper</span></span>
<span class="line"><span>serio_raw              20480  0</span></span>
<span class="line"><span>sysfillrect            16384  1 drm_kms_helper</span></span>
<span class="line"><span>sysimgblt              16384  1 drm_kms_helper</span></span>
<span class="line"><span>soundcore              16384  1 snd</span></span>
<span class="line"><span>mac_hid                16384  0</span></span>
<span class="line"><span>sch_fq_codel           20480  2</span></span>
<span class="line"><span>parport_pc             40960  0</span></span>
<span class="line"><span>ppdev                  24576  0</span></span>
<span class="line"><span>lp                     20480  0</span></span>
<span class="line"><span>parport                53248  3 parport_pc,lp,ppdev</span></span>
<span class="line"><span>ip_tables              28672  0</span></span>
<span class="line"><span>x_tables               40960  1 ip_tables</span></span>
<span class="line"><span>autofs4                45056  2</span></span>
<span class="line"><span>raid10                 57344  0</span></span>
<span class="line"><span>raid456               155648  0</span></span>
<span class="line"><span>async_raid6_recov      24576  1 raid456</span></span>
<span class="line"><span>async_memcpy           20480  2 raid456,async_raid6_recov</span></span>
<span class="line"><span>async_pq               24576  2 raid456,async_raid6_recov</span></span>
<span class="line"><span>async_xor              20480  3 async_pq,raid456,async_raid6_recov</span></span>
<span class="line"><span>async_tx               20480  5 async_pq,async_memcpy,async_xor,raid456,async_raid6_re</span></span>
<span class="line"><span>                                cov</span></span>
<span class="line"><span>xor                    24576  1 async_xor</span></span>
<span class="line"><span>raid6_pq              114688  3 async_pq,raid456,async_raid6_recov</span></span>
<span class="line"><span>libcrc32c              16384  1 raid456</span></span>
<span class="line"><span>raid1                  45056  0</span></span>
<span class="line"><span>raid0                  24576  0</span></span>
<span class="line"><span>multipath              20480  0</span></span>
<span class="line"><span>linear                 20480  0</span></span>
<span class="line"><span>hid_generic            16384  0</span></span>
<span class="line"><span>psmouse               151552  0</span></span>
<span class="line"><span>i2c_i801               32768  0</span></span>
<span class="line"><span>pata_acpi              16384  0</span></span>
<span class="line"><span>lpc_ich                24576  0</span></span>
<span class="line"><span>usbhid                 53248  0</span></span>
<span class="line"><span>hid                   126976  2 usbhid,hid_generic</span></span>
<span class="line"><span>e1000e                245760  0</span></span>
<span class="line"><span>floppy                 81920  0</span></span></code></pre></div><p>在上面的输出中：</p><ul><li><code>Module</code> 显示每个模块的名称</li><li><code>Size</code> 显示每个模块的大小（并不是它们占的内存大小）</li><li><code>Used by</code> 显示每个模块被使用的次数和使用它们的模块</li></ul><p>显然，这里有<em>很多</em>模块。加载的模块数量取决于你的系统和版本以及正在运行的内容。我们可以这样计数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsmod | wc -l</span></span>
<span class="line"><span>67</span></span></code></pre></div><p>要查看系统中可用的模块数（不止运行当中的），试试这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ modprobe -c | wc -l</span></span>
<span class="line"><span>41272</span></span></code></pre></div><h3 id="与内核模块相关的其他命令" tabindex="-1">与内核模块相关的其他命令 <a class="header-anchor" href="#与内核模块相关的其他命令" aria-label="Permalink to “与内核模块相关的其他命令”">​</a></h3><p>Linux 提供了几条用于罗列、加载及卸载、测试，以及检查模块状态的命令。</p><ul><li><code>depmod</code> —— 生成 <code>modules.dep</code> 和映射文件</li><li><code>insmod</code> —— 一个往 Linux 内核插入模块的程序</li><li><code>lsmod</code> —— 显示 Linux 内核中模块状态</li><li><code>modinfo</code> —— 显示 Linux 内核模块信息</li><li><code>modprobe</code> —— 添加或移除 Linux 内核模块</li><li><code>rmmod</code> —— 一个从 Linux 内核移除模块的程序</li></ul><h3 id="显示内置的内核模块" tabindex="-1">显示内置的内核模块 <a class="header-anchor" href="#显示内置的内核模块" aria-label="Permalink to “显示内置的内核模块”">​</a></h3><p>正如前文所说，<code>lsmod</code> 命令是显示内核模块最方便的命令。然而，也有其他方式可以显示它们。<code>modules.builtin</code> 文件中列出了所有构建在内核中的模块，在 <code>modprobe</code> 命令尝试添加文件中的模块时会使用它。注意，以下命令中的 <code>$(uname -r)</code> 提供了内核版本的名称。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ more /lib/modules/$(uname -r)/modules.builtin | head -10</span></span>
<span class="line"><span>kernel/arch/x86/crypto/crc32c-intel.ko</span></span>
<span class="line"><span>kernel/arch/x86/events/intel/intel-uncore.ko</span></span>
<span class="line"><span>kernel/arch/x86/platform/intel/iosf_mbi.ko</span></span>
<span class="line"><span>kernel/mm/zpool.ko</span></span>
<span class="line"><span>kernel/mm/zbud.ko</span></span>
<span class="line"><span>kernel/mm/zsmalloc.ko</span></span>
<span class="line"><span>kernel/fs/binfmt_script.ko</span></span>
<span class="line"><span>kernel/fs/mbcache.ko</span></span>
<span class="line"><span>kernel/fs/configfs/configfs.ko</span></span>
<span class="line"><span>kernel/fs/crypto/fscrypto.ko</span></span></code></pre></div><p>你可以使用 <code>modinfo</code> 获得一个模块的更多细节，虽然没有对模块提供的服务的简单说明。下面输出内容中省略了冗长的签名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ modinfo floppy | head -16</span></span>
<span class="line"><span>filename:       /lib/modules/5.0.0-13-generic/kernel/drivers/block/floppy.ko</span></span>
<span class="line"><span>alias:          block-major-2-*</span></span>
<span class="line"><span>license:        GPL</span></span>
<span class="line"><span>author:         Alain L. Knaff</span></span>
<span class="line"><span>srcversion:     EBEAA26742DF61790588FD9</span></span>
<span class="line"><span>alias:          acpi*:PNP0700:*</span></span>
<span class="line"><span>alias:          pnp:dPNP0700*</span></span>
<span class="line"><span>depends:</span></span>
<span class="line"><span>retpoline:      Y</span></span>
<span class="line"><span>intree:         Y</span></span>
<span class="line"><span>name:           floppy</span></span>
<span class="line"><span>vermagic:       5.0.0-13-generic SMP mod_unload</span></span>
<span class="line"><span>sig_id:         PKCS#7</span></span>
<span class="line"><span>signer:</span></span>
<span class="line"><span>sig_key:</span></span>
<span class="line"><span>sig_hashalgo:   md4</span></span></code></pre></div><p>你可以使用 <code>modprobe</code> 命令加载或卸载模块。使用下面这条命令，你可以找到特定模块关联的内核对象：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find /lib/modules/$(uname -r) -name floppy*</span></span>
<span class="line"><span>/lib/modules/5.0.0-13-generic/kernel/drivers/block/floppy.ko</span></span></code></pre></div><p>如果你想要加载模块，你可以使用这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo modprobe floppy</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>很明显，内核模块的加载和卸载非常重要。它使得 Linux 系统比使用通用内核运行时更加灵活和高效。这同样意味着你可以进行重大更改而无需重启，例如添加硬件。</p><hr>`,31)),i("p",null,[s[1]||(s[1]=n("via: ",-1)),p(a,{href:"https://www.networkworld.com/article/3391362/looking-into-linux-modules.html"},{default:e(()=>[...s[0]||(s[0]=[n("https://www.networkworld.com/article/3391362/looking-into-linux-modules.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=n("作者：",-1)),p(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:e(()=>[...s[2]||(s[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=n(" 选题：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 译者：",-1)),p(a,{href:"https://github.com/LazyWolfLin"},{default:e(()=>[...s[4]||(s[4]=[n("LazyWolfLin",-1)])]),_:1}),s[9]||(s[9]=n(" 校对：",-1)),p(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原创编译，",-1)),p(a,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[n("Linux中国",-1)])]),_:1}),s[14]||(s[14]=n(" 荣誉推出",-1))])])}const x=l(r,[["render",_]]);export{y as __pageData,x as default};
